# the starting list is the rule-picked planted visit with at least 30 trees (the planted scenario list of Table 4) in place of the 11-tree PSP 111 2012 list. Equations koa 1.15.0.
suppressMessages({library(data.table); library(ggplot2); library(patchwork)}); setwd("~/jobs/koa_1150_20261121"); source("scripts/utils.R"); source("release/koa_step.R"); options(width = 230)
ND <- as.integer(Sys.getenv("KOA_NDRAW", "500")); NDc <- as.integer(Sys.getenv("KOA_NDRAW_COV", "300")); NC <- as.integer(Sys.getenv("KOA_CORES", "6")); RNGkind("L'Ecuyer-CMRG"); set.seed(20261118); dir.create("ms_v136", showWarnings = FALSE)
f <- readRDS("frames/frames.rds"); tr <- f$tr
th <- fread("~/jobs/koa_v105final_20261103/inputs/psp_origin_thinning_2026-09-16_DATA.csv"); REM <- th[removal_t1_years != "" & !is.na(removal_t1_years), .(yr = as.integer(unlist(strsplit(as.character(removal_t1_years), ";")))), by = .(Data, Install = as.character(Install))]
flagrem <- function(x, strict) { x <- copy(x); x[, rid__ := .I]; k <- merge(x[, .(rid__, Data, Install = as.character(Install), Measure, e_Measure)], REM, by = c("Data", "Install"), allow.cartesian = TRUE); k <- if (strict) k[yr > Measure & yr < e_Measure] else k[yr > Measure & yr <= e_Measure]; x[, rem__ := rid__ %in% k$rid__]; x }   # PSP thinning removals (psp_origin_thinning_2026-09-16_DATA.csv): mortality intervals ending in or spanning a removal year are censored; increment intervals with a removal year strictly inside are dropped
 cf <- koa_read_coef("release/koa_final_equations.csv"); FT <- readRDS("out/rdbyi2_fits.rds"); BT <- readRDS("out/rdbyi2_boot.rds"); K <- BT$K; bs <- FT$bs; bg <- FT$bg; bm <- FT$bm; E2 <- readRDS("out/E2_height_cr3.rds"); bH <- E2$boot[complete.cases(E2$boot), , drop = FALSE]
s1p <- function(b, lbyi, pl) exp(b[[1]] + b[[2]] * lbyi + b[[3]] * pl); kS <- 1:3; kG <- 4:9; kM <- 10:17; cat("bootstrap rows:", nrow(K), "; S1 residual sd (ln scale):", round(FT$s1_resid_sd, 3), "; sigma", round(FT$sigma, 4), " tau", round(FT$tau, 4), " delta", round(FT$delta, 4), " phi", round(FT$phi, 4), "\n")
xm <- function(S, BAL, BA, SDI, sm, byi, pl) cbind(1, log(S + 1), S, BAL / pmax(BA, 1e-6) * SDI / sm, log(byi), pl)
thB <- readRDS("out/height_increment_44.rds")$FF$J1$th; kh3 <- function(d, byi) 1.37 + (exp(thB[[1]] + thB[[2]] * log(byi)) - 1.37) * (1 - exp(-exp(thB[[7]]) * d))^exp(thB[[8]])
IB <- readRDS("out/ingrowth_50.rds"); IBT <- IB$BT[IB$BT[, 4] == 1 & complete.cases(IB$BT), 1:3, drop = FALSE]; irate <- function(b, mu2, q) (1 - exp(-9 * exp(b[[1]] + b[[2]] * q))) * mu2 * 59.5 / 9
IG <- function(pl) if (pl == 0) function(q) irate(IB$b, IB$mu2, q) else NULL; IGd <- function() { k <- IBT[sample(nrow(IBT), 1), ]; function(q) irate(k[1:2], k[[3]], q) }; cat("ingrowth bootstrap rows:", nrow(IBT), "\n")
 hB2 <- function(H, x, lb, pl) { H <- pmax(H, 0.5); A. <- exp(thB[[1]] + thB[[2]] * lb); cc <- exp(thB[[4]]); pmax(cc * exp(thB[[3]] + thB[[6]] * pl) * H * ((A. / H)^(1 / cc) - 1), 0) * exp(thB[[5]] * x) }; cat("J1:", round(thB, 5), "\n")
simx <- function(dbh, ht, ex, byi, pl, years, sm, bg. = bg, bm. = bm, R = 1, sig = 0, dl = 0, ph = 1, ing = NULL) { out <- matrix(NA_real_, years + 1, 7, dimnames = list(NULL, c("BA", "TPH", "QMD", "HT", "VOL", "RD", "SDI")))
  for (y in 0:years) { s <- koa_stand(dbh, ht, ex); out[y + 1, ] <- c(s$BA, s$TPH, s$QMD, s$HT, 0.40 * s$BA * s$HT, s$SDI / sm, s$SDI); if (y == years) break
    bal <- koa_bal(dbh, s$ba); rd <- s$SDI / sm; g <- as.numeric(exp(xm(dbh, bal, s$BA, s$SDI, sm, byi, pl) %*% bg.)) * R; if (sig > 0) { s2 <- log(1 + (sig * pmax(g, 0.01)^(dl - 1))^2); g <- g * exp(rnorm(length(g), 0, sqrt(s2)) - s2 / 2) }
    pm <- 1 - exp(-ph * exp(as.numeric(cbind(1, log(dbh + 1), dbh, dbh^2, bal, log(max(rd, 0.001)), log(byi), pl) %*% bm.))); ht <- ht + hB2(ht, bal / max(s$BA, 1e-6) * rd, log(byi), pl); dbh <- dbh + g; ex <- ex * (1 - pm); if (!is.null(ing)) { ni <- ing(s$QMD); if (is.finite(ni) && ni > 0) { dbh <- c(dbh, 12.7); ht <- c(ht, kh3(12.7, byi)); ex <- c(ex, ni) } } }
  out }
draw <- function(lbyi, pl, site) { k <- K[sample(nrow(K), 1), ]; t2 <- log(1 + FT$tau^2); list(sm = s1p(k[kS], lbyi, pl) * (if (site) exp(rnorm(1, 0, FT$s1_resid_sd)) else 1), bg = k[kG], bm = k[kM], R = exp(rnorm(1, 0, sqrt(t2)) - t2 / 2), ph = if (FT$phi > 0) rgamma(1, 1 / FT$phi, 1 / FT$phi) else 1) }
onedraw <- function(dbh, ht, ex, byi, pl, years, site) { q <- draw(log(byi), pl, site); simx(dbh, ht, ex, byi, pl, years, q$sm, q$bg, q$bm, q$R, FT$sigma, FT$delta, q$ph, ing = if (pl == 0) IGd() else NULL) }
vis <- tr[Status == "live" & !is.na(DBH) & DBH > 0, .(n = .N, q = sqrt(sum(DBH^2 * EXPF_c) / sum(EXPF_c))), by = .(pid, Measure, planted)][n >= 10]; byiq <- unique(tr[, .(pid, planted, BYI)])[, .(lo = quantile(BYI, .1), md = quantile(BYI, .5), hi = quantile(BYI, .9)), by = planted]; pick <- rbind(vis[planted == 0][which.min(abs(q - quantile(q, 0.25)))], { vp <- tr[Status == "live" & !is.na(DBH) & DBH > 0 & planted == 1, .(n = .N, N = sum(EXPF_c), q = sqrt(sum(DBH^2 * EXPF_c) / sum(EXPF_c))), by = .(pid, Measure, planted)][n >= 30]; vp[, dd := abs((log(q) - median(log(q))) / sd(log(q))) + abs((log(N) - median(log(N))) / sd(log(N)))]; vp[which.min(dd), .(pid, Measure, planted, n, q)] })  # 1.15.0 Bakuzis follow-up: planted scenario list = visit with 30+ trees closest to the median QMD and stems of such visits
getL <- function(p) { pv <- pick[planted == p]; L <- tr[pid == pv$pid & Measure == pv$Measure & Status == "live" & !is.na(DBH) & DBH > 0]; L[is.na(HT) | HT < 1.37, HT := kh3(DBH, BYI)]; L }
# ---- (6) workbook grid ----
pv <- pick[planted == 1]; cat("workbook starting visit:", pv$pid, pv$Measure, "trees", pv$n, "\n"); L <- tr[pid == pv$pid & Measure == pv$Measure & Status == "live" & !is.na(DBH) & DBH > 0]; q0 <- sqrt(sum(L$DBH^2 * L$EXPF_c) / sum(L$EXPF_c)); d0 <- L$DBH * 7.24 / q0; h0 <- kh3(d0, 340); SITES <- c(Excellent = 450, Good = 340, Marginal = 230, `Low Feasibility` = 120); DENS <- c(100, 200, 300, 400); AC <- 2.471054
rq <- quantile(FT$s1_resid[planted == 1, r], c(.1, .9)); MULT <- c(central = 1, low = exp(rq[[1]]), high = exp(rq[[2]])); cat("\n(6) workbook grid. Starting list: trees", nrow(L), ", QMD rescaled to 7.24 cm, starting BA-weighted height", round(sum(h0 * d0^2) / sum(d0^2), 2), "m. SDImax multipliers for the low and high cases (10th and 90th percentile of planted plot residuals about S1):", round(MULT[2:3], 3), "\n")
Gd <- rbindlist(lapply(names(MULT), function(sn) rbindlist(lapply(names(SITES), function(s) rbindlist(lapply(DENS, function(n) { sm <- s1p(bs, log(SITES[[s]]), 1) * MULT[[sn]]; z <- as.data.table(simx(d0, kh3(d0, SITES[[s]]), L$EXPF_c * n * AC / sum(L$EXPF_c), SITES[[s]], 1, 199, sm)); cbind(sdimax = sn, site = s, byi = SITES[[s]], stems_ac = n, sdimax_value = sm, age = 1:200, z) }))))))
Gd[, `:=`(BA_ft2ac = BA * 4.356, QMD_in = QMD / 2.54, TPA = TPH / AC, HT_ft = HT * 3.28084, VOL_ft3ac = VOL * 14.2913)]; anchor <- Gd[sdimax == "central" & site == "Good" & stems_ac == 200 & age == 45, HT]; Gd[, VBAR := 95 * HT / anchor]; cat("anchor height:", round(anchor, 2), "m; SDImax by site class (central):", paste(names(SITES), round(s1p(bs, log(SITES), 1)), collapse = "; "), "\n"); fwrite(Gd, "out/workbook_grid_72.csv")
lg <- function(a, y) { st <- c(A = max(y) * 1.02, B = a[which.min(abs(y - max(y) / 2))], C = 6); o <- optim(st, function(p) sum((y - p[1] / (1 + exp(-(a - p[2]) / p[3])))^2), method = "BFGS", control = list(maxit = 2000, reltol = 1e-12)); o$par }
LG <- Gd[, { p60 <- lg(age[age <= 60], BA_ft2ac[age <= 60]); p100 <- lg(age[age <= 100], BA_ft2ac[age <= 100]); f60 <- p60[1] / (1 + exp(-(age - p60[2]) / p60[3])); f100 <- p100[1] / (1 + exp(-(age - p100[2]) / p100[3]))
  .(A = p60[1], B = p60[2], C = p60[3], rmse = sqrt(mean((BA_ft2ac - f60)[age <= 60]^2)), rmse_pct = 100 * sqrt(mean((BA_ft2ac - f60)[age <= 60]^2)) / mean(BA_ft2ac[age <= 60]), e40 = (BA_ft2ac - f60)[age == 40], e52 = (BA_ft2ac - f60)[age == 52], A100 = p100[1], B100 = p100[2], C100 = p100[3], rmse_pct100 = 100 * sqrt(mean((BA_ft2ac - f100)[age <= 100]^2)) / mean(BA_ft2ac[age <= 100])) }, by = .(sdimax, site, byi, stems_ac)]; fwrite(LG, "out/workbook_logistic_72.csv")
DG <- Gd[, .(BA20 = BA_ft2ac[age == 20], BA40 = BA_ft2ac[age == 40], BA52 = BA_ft2ac[age == 52], BA100 = BA_ft2ac[age == 100], BA200 = BA_ft2ac[age == 200], peakBA = max(BA_ft2ac), peak_age = age[which.max(BA_ft2ac)], decline_pct = 100 * (1 - BA_ft2ac[age == 200] / max(BA_ft2ac)), stems52 = TPA[age == 52], qmd52 = QMD_in[age == 52], reineke = coef(lm(log(TPA) ~ log(QMD_in)))[[2]], rises_to_peak = all(diff(BA_ft2ac[age <= age[which.max(BA_ft2ac)]]) >= -1e-9), rd_max = max(RD), sdi_max = max(SDI)), by = .(sdimax, site, byi, stems_ac, sdimax_value)]; fwrite(DG, "out/workbook_diag_72.csv")
wc <- dcast(Gd[sdimax == "central"], stems_ac + age ~ site, value.var = "BA_ft2ac"); X8 <- wc[, .(first_inversion = { o <- which(!(`Low Feasibility` <= Marginal + 1e-9 & Marginal <= Good + 1e-9 & Good <= Excellent + 1e-9)); if (length(o)) age[o[1]] else NA_integer_ }, exc_minus_low_100 = (Excellent - `Low Feasibility`)[age == 100], low_minus_exc_200 = (`Low Feasibility` - Excellent)[age == 200]), by = stems_ac]; fwrite(X8, "out/workbook_crossover_72.csv")
